CREATE TABLE IF NOT EXISTS document_scan_evidence (
  id INTEGER PRIMARY KEY,
  document_id INTEGER NOT NULL UNIQUE REFERENCES documents(id),
  sha256_hash TEXT NOT NULL CHECK(length(sha256_hash) = 64),
  scanner_id TEXT NOT NULL CHECK(length(trim(scanner_id)) BETWEEN 1 AND 160),
  scanner_version TEXT CHECK(scanner_version IS NULL OR length(scanner_version) BETWEEN 1 AND 160),
  scanned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  result TEXT NOT NULL CHECK(result = 'clean'),
  evidence_ref TEXT,
  CHECK(evidence_ref IS NULL OR length(evidence_ref) BETWEEN 1 AND 512)
);
CREATE TRIGGER document_scan_evidence_no_update BEFORE UPDATE ON document_scan_evidence BEGIN SELECT RAISE(ABORT, 'document scan evidence is append-only'); END;
CREATE TRIGGER document_scan_evidence_no_delete BEFORE DELETE ON document_scan_evidence BEGIN SELECT RAISE(ABORT, 'document scan evidence is append-only'); END;
